from typing import List, Dict, Any

class ExtractedText:
    def __init__(self, text: str, confidence: float = None):
        self.text = text
        self.confidence = confidence

    def to_dict(self):
        return {"text": self.text, "confidence": self.confidence}

class ExtractedBlock:
    def __init__(self, content: str, bounding_box: List[float], kind: str, confidence: float = None):
        self.content = content
        self.bounding_box = bounding_box
        self.kind = kind
        self.confidence = confidence

    def to_dict(self):
        return {"content": self.content, "bounding_box": self.bounding_box, "kind": self.kind, "confidence": self.confidence}

class ExtractedTable:
    def __init__(self, rows: List[List[Dict[str, Any]]], bounding_box: List[float], confidence: float = None):
        self.rows = rows
        self.bounding_box = bounding_box
        self.confidence = confidence

    def to_dict(self):
        return {"rows": self.rows, "bounding_box": self.bounding_box, "confidence": self.confidence}

class ExtractedKeyValuePair:
    def __init__(self, key: ExtractedText, value: ExtractedText, confidence: float = None):
        self.key = key
        self.value = value
        self.confidence = confidence

    def to_dict(self):
        return {"key": self.key.to_dict() if self.key else None, "value": self.value.to_dict() if self.value else None, "confidence": self.confidence}

from document_client import get_image_analysis_client
from document_models import ExtractedText
from azure.ai.vision.imageanalysis import VisualFeatures

def extract_text_from_image(image_data: bytes) -> ExtractedText:
    client = get_image_analysis_client()
    features = [VisualFeatures.READ]

    # Authenticate and send the image stream to the Image Analysis service
    result = client.analyze(image_data=image_data, visual_features=features)

    if result.read and result.read.blocks:
        full_text = []
        for block in result.read.blocks:
            for line in block.lines:
                full_text.append(line.text)
        return ExtractedText(text="\n".join(full_text))
    return ExtractedText(text="")

from document_client import get_document_intelligence_client
from document_models import ExtractedTable

def extract_tables_from_document(document_data: bytes, content_type: str) -> list[ExtractedTable]:
    client = get_document_intelligence_client()

    poller = client.begin_analyze_document(model_id="prebuilt-layout", document=document_data, content_type=content_type)
    result = poller.result()

    extracted_tables = []
    if result.tables:
        for table in result.tables:
            rows = []
            for row_idx in range(table.row_count):
                current_row = []
                for col_idx in range(table.column_count):
                    cell_content = ""
                    for cell in table.cells:
                        if cell.row_index == row_idx and cell.column_index == col_idx:
                            cell_content = cell.content
                            break
                    current_row.append({"content": cell_content})
                rows.append(current_row)

            bounding_box = []
            if table.bounding_regions:
                for region in table.bounding_regions:
                    # Assuming a simple case where we take the first bounding region, or combine them if necessary
                    # For simplicity, we'll just take the polygon points as a flat list
                    bounding_box.extend([p.x, p.y for p in region.polygon])

            extracted_tables.append(ExtractedTable(rows=rows, bounding_box=bounding_box, confidence=table.confidence))

    return extracted_tables

from document_client import get_language_client
from azure.ai.textanalytics import TextDocumentInput
from typing import List, Dict, Any

def extract_fields_from_text(text: str, project_name: str, deployment_name: str) -> List[Dict[str, Any]]:
    client = get_language_client()

    document = [TextDocumentInput(id="1", text=text)]

    # For custom text extraction, you would typically use a custom trained model.
    # The example below assumes a custom deployment that can extract entities.
    # Replace with your actual project and deployment names.
    response = client.begin_analyze_actions(
        document,
        actions=[
            {"kind": "CustomEntityRecognition", "document_languange": "en", "project_name": project_name, "deployment_name": deployment_name}
        ]
    ).result()

    extracted_fields = []
    for result in response:
        if result.is_error:
            print(f"...Is an error with code '{result.code}' and message '{result.message}'")
        else:
            for entity in result.entities:
                extracted_fields.append({"text": entity.text, "category": entity.category, "confidence_score": entity.confidence_score, "offset": entity.offset, "length": entity.length})

    return extracted_fields
